# ==============================================================================
# Validation Regression Suite for ClinicoPath::jjpiestats
# Generated by /validate-function jjpiestats depth=exhaustive (2026-11-08)
# Covers Claims [C01] - [C37]. Open defects are guarded by skip("VAL-jjpiestats-NN ...")
# with the true mathematical/clinical expected values preserved (Rule E6).
# ==============================================================================

capture_jjpie_plot <- function(options, data, method_name = ".plot1") {
  a <- ClinicoPath:::jjpiestatsClass$new(options = options, data = data)
  suppressWarnings(suppressMessages(a$run()))
  priv <- a$.__enclos_env__$private
  img_name <- switch(method_name,
    ".plot1"     = "plot1",
    ".plot2"     = "plot2",
    ".plot4"     = "plot4",
    ".plotDonut" = "donutPlot"
  )
  img <- a$results[[img_name]]
  last_printed <- NULL
  env_here <- environment()
  f <- tempfile(fileext = ".pdf")
  grDevices::pdf(f)
  suppressMessages(trace(
    base::print,
    tracer = bquote(assign("last_printed", x, envir = .(env_here))),
    print = FALSE
  ))
  on.exit({
    suppressMessages(try(untrace(base::print), silent = TRUE))
    try(grDevices::dev.off(), silent = TRUE)
    unlink(f)
  }, add = TRUE)
  fn <- priv[[method_name]]
  suppressWarnings(suppressMessages(
    fn(image = img, ggtheme = ggplot2::theme_bw(), theme = list(palette = "jmv"))
  ))
  last_printed
}

strip_html_tags <- function(x) {
  txt <- paste(as.character(if (is.null(x)) "" else x), collapse = " ")
  gsub("^[[:space:]]+|[[:space:]]+$", "",
       gsub("[[:space:]]+", " ", gsub("</?[a-zA-Z][^>]*>", " ", txt)))
}

extract_sub_num <- function(txt, pat) {
  txt <- paste(txt, collapse = " ")
  m <- regmatches(txt, regexec(pat, txt))[[1]]
  if (length(m) >= 2L) as.numeric(m[2L]) else NA_real_
}

d_a1_val <- data.frame(
  dep = factor(rep(c("A", "B", "C"), c(6, 4, 2)), levels = c("A", "B", "C"))
)

d_a4_val <- data.frame(
  dep = factor(rep(c("Yes", "No", "Yes", "No"), c(30, 10, 10, 30)), levels = c("Yes", "No")),
  grp = factor(rep(c("Arm1", "Arm2"), each = 40), levels = c("Arm1", "Arm2"))
)

d_a5_val <- data.frame(
  dep = factor(rep(c("Yes", "No", "Yes", "No"), c(2, 10, 8, 6)), levels = c("Yes", "No")),
  grp = factor(rep(c("ArmA", "ArmB"), c(12, 14)), levels = c("ArmA", "ArmB"))
)

d_bentur_val <- data.frame(
  Pre  = factor(c("Neg", "Pos", "Neg", "Pos"), levels = c("Neg", "Pos")),
  Post = factor(c("Neg", "Neg", "Pos", "Pos"), levels = c("Neg", "Pos")),
  n    = c(2, 7, 1, 11)
)

d_cavo_val <- data.frame(
  Pre  = factor(c("Neg", "Pos", "Neg", "Pos"), levels = c("Neg", "Pos")),
  Post = factor(c("Neg", "Neg", "Pos", "Pos"), levels = c("Neg", "Pos")),
