test_that("[C01] 1-way pie slice counts and percentages match hand-calculated proportions", {
  # Hand derivation: n = 12 with counts (6, 4, 2) -> percentages (50, 100/3, 50/3)
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", resultssubtitle = TRUE, label = "both", digits = 4
  )
  p <- capture_jjpie_plot(opts, d_a1_val, ".plot1")
  df_desc <- p$data[order(as.character(p$data$dep)), ]
  expect_identical(df_desc$counts, c(6L, 4L, 2L))
  expect_equal(df_desc$perc, c(50, 100 / 3, 50 / 3), tolerance = 1e-12)
})

test_that("[C02] 1-way frequentist goodness-of-fit chi-square, p-value, and Pearson C match closed form", {
  # Hand derivation: E = (4, 4, 4), chi2 = (6-4)^2/4 + 0 + (2-4)^2/4 = 2.0, df = 2, p = exp(-1) = 0.3678794, C = sqrt(2/14) = 0.3779645
  opts1 <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", resultssubtitle = TRUE, digits = 4)
  p1 <- capture_jjpie_plot(opts1, d_a1_val, ".plot1")
  sub1 <- paste(deparse(p1$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub1, '\\)\\" == \\"([0-9.eE+-]+)\\"'), 2.0, tolerance = 1e-4)
  expect_equal(extract_sub_num(sub1, 'italic\\(p\\) == \\"([0-9.eE+-]+)\\"'), exp(-1), tolerance = 1e-4)
  expect_equal(extract_sub_num(sub1, '\\["Pearson"\\] == \\"([0-9.eE+-]+)\\"'), sqrt(2 / 14), tolerance = 1e-4)

  # Custom ratio = (0.5, 0.25, 0.25) -> E = (6, 3, 3), chi2 = 2/3 = 0.6666667, C = sqrt(1/19) = 0.2294157
  opts2 <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", ratio = "0.5,0.25,0.25", resultssubtitle = TRUE, digits = 4
  )
  p2 <- capture_jjpie_plot(opts2, d_a1_val, ".plot1")
  sub2 <- paste(deparse(p2$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub2, '\\)\\" == \\"([0-9.eE+-]+)\\"'), 2 / 3, tolerance = 1e-4)
  expect_equal(extract_sub_num(sub2, '\\["Pearson"\\] == \\"([0-9.eE+-]+)\\"'), sqrt(1 / 19), tolerance = 1e-4)

  d_unused <- data.frame(
    dep = factor(rep(c("A", "B"), c(30, 30)), levels = c("A", "B", "UnusedLevel"))
  )
  p_unused <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", resultssubtitle = TRUE, digits = 4),
    d_unused, ".plot1"
  )
  sub_unused <- paste(deparse(p_unused$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub_unused, '\\)\\" == \\"([0-9.eE+-]+)\\"'), 0.0, tolerance = 1e-4)
})

test_that("[C03] 1-way Bayesian Dirichlet-multinomial log_e(BF01) matches exact Beta-binomial integral", {
  # Exact integral: 40*log(0.5) - (lgamma(1) - lgamma(41) + lgamma(30.5) + lgamma(10.5) - 2*lgamma(0.5)) = -3.154614
  d_a3 <- data.frame(dep = factor(rep(c("Pos", "Neg"), c(30, 10)), levels = c("Pos", "Neg")))
  exact_log_bf01 <- 40 * log(0.5) - (lgamma(1) - lgamma(41) + lgamma(30.5) + lgamma(10.5) - 2 * lgamma(0.5))
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", typestatistics = "bayes", seed = 20250101, resultssubtitle = TRUE, digits = 3
  )
  p <- capture_jjpie_plot(opts, d_a3, ".plot1")
  sub <- paste(deparse(p$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub, 'BF\\["01"\\]\\) == \\"([0-9.eE+-]+)\\"'), exact_log_bf01, tolerance = 0.02)
})

test_that("[C04] 2-way pie slice conditional percentages and geom_col fill geometry match within-group proportions", {
  # Hand derivation: Arm1 = (30, 10) -> (75%, 25%); Arm2 = (10, 30) -> (25%, 75%)
  opts <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", resultssubtitle = TRUE, digits = 4)
  p <- capture_jjpie_plot(opts, d_a4_val, ".plot2")
  expect_equal(p$data$perc[order(p$data$grp, p$data$dep)], c(75, 25, 25, 75), tolerance = 1e-12)
  expect_identical(sum(p$data$counts), 80L)
  expect_equal(as.numeric(tapply(p$data$perc, p$data$grp, sum)), c(100, 100), tolerance = 1e-12)
  b <- ggplot2::ggplot_build(p)
  bars <- b$data[[1]]
  expect_equal(c(max(bars$ymax[bars$PANEL == 1]), max(bars$ymax[bars$PANEL == 2])), c(1, 1), tolerance = 1e-12)
})

test_that("[C05] 2-way unpaired Pearson chi-square and Bergsma (2013) bias-corrected Cramer's V match closed form", {
  # Hand derivation: chi2 = 4*(10^2/20) = 20.0, df = 1, V_Bergsma = sqrt((20/80 - 1/79) / (1 - 1/79)) = sqrt(18.75/78) = 0.4902903
  opts <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", resultssubtitle = TRUE, digits = 4)
  p <- capture_jjpie_plot(opts, d_a4_val, ".plot2")
  sub <- paste(deparse(p$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub, '\\)\\" == \\"([0-9.eE+-]+)\\"'), 20.0, tolerance = 1e-4)
  expect_equal(extract_sub_num(sub, '\\["Cramer"\\] == \\"([0-9.eE+-]+)\\"'), sqrt(18.75 / 78), tolerance = 1e-4)

  # Duplicating every row doubles Pearson chi2 (20 -> 40)
  p_2n <- capture_jjpie_plot(opts, rbind(d_a4_val, d_a4_val), ".plot2")
  sub_2n <- paste(deparse(p_2n$labels$subtitle), collapse = "")
  expect_equal(extract_sub_num(sub_2n, '\\)\\" == \\"([0-9.eE+-]+)\\"'), 40.0, tolerance = 1e-4)

  d_unused2 <- data.frame(
    dep = factor(rep(c("A", "B"), c(30, 30)), levels = c("A", "B", "UnusedLevel")),
    grp = factor(rep(c("X", "Y", "X", "Y"), c(15, 15, 15, 15)), levels = c("X", "Y"))
  )
  p_u2 <- capture_jjpie_plot(opts, d_unused2, ".plot2")
  expect_false(is.null(p_u2$labels$subtitle))
})

test_that("[C06] Sparse 2x2 table swaps subtitle to Fisher's exact test with conditional MLE OR", {
  # stats::fisher.test(matrix(c(2, 10, 8, 6), 2, 2)) -> p = 0.0510927, conditional MLE OR = 0.1636050
  ft_ref <- stats::fisher.test(matrix(c(2, 10, 8, 6), 2, 2))
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", group = "grp", resultssubtitle = TRUE, digits = 4, conflevel = 0.95
  )
  p <- capture_jjpie_plot(opts, d_a5_val, ".plot2")
  sub <- paste(deparse(p$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub, '\\["Fisher"\\][[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), ft_ref$p.value, tolerance = 1e-3)
  expect_equal(extract_sub_num(sub, 'italic\\("OR"\\)\\)[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), unname(ft_ref$estimate), tolerance = 1e-2)

  # Swapping group level order inverts conditional MLE OR (1 / OR = 6.1605)
  d_swap <- d_a5_val
  d_swap$grp <- factor(d_swap$grp, levels = c("ArmB", "ArmA"))
  p_swap <- capture_jjpie_plot(opts, d_swap, ".plot2")
  sub_swap <- paste(deparse(p_swap$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub_swap, 'italic\\("OR"\\)\\)[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), 1 / unname(ft_ref$estimate), tolerance = 1e-3)

  d_z1 <- data.frame(
    dep = factor(c("Yes", "No", "Yes", "No"), levels = c("Yes", "No")),
    grp = factor(c("ArmA", "ArmA", "ArmB", "ArmB"), levels = c("ArmA", "ArmB")),
    n   = c(0, 10, 8, 6)
  )
  d_z2 <- d_z1
  d_z2$grp <- factor(d_z2$grp, levels = c("ArmB", "ArmA"))
  opts_z <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", counts = "n", resultssubtitle = TRUE)
  sub_z1 <- paste(deparse(capture_jjpie_plot(opts_z, d_z1, ".plot2")$labels$subtitle), collapse = " ")
  sub_z2 <- paste(deparse(capture_jjpie_plot(opts_z, d_z2, ".plot2")$labels$subtitle), collapse = " ")
  expect_identical(grepl('widehat\\(italic\\("OR"\\)\\)', sub_z1), grepl('widehat\\(italic\\("OR"\\)\\)', sub_z2))

  # Sparse 2x2 with bfmessage = TRUE preserves Bayes factor caption alongside Fisher exact subtitle
  p_bf_sp <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(
      dep = "dep", group = "grp", resultssubtitle = TRUE, bfmessage = TRUE
    ),
    d_a5_val, ".plot2"
  )
  expect_false(is.null(p_bf_sp$labels$caption))
})

test_that("[C07] Paired 2x2 McNemar chi-square, p-value, and Cohen's g match Fagerland et al. (2013, Table 6)", {
  # Fagerland et al. (2013) Table 6:
  # Bentur (2,1,7,11): chi2 = 36/8 = 4.5, p = 0.03389485, g = 7/8 - 0.5 = 0.375
  # Cavo (59,6,16,80): chi2 = 100/22 = 4.545455, p = 0.03300626, g = 5/22 = 0.2272727
  opts_b <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "Pre", group = "Post", counts = "n", paired = TRUE, resultssubtitle = TRUE, digits = 4
  )
  p_b <- capture_jjpie_plot(opts_b, d_bentur_val, ".plot2")
  sub_b <- paste(deparse(p_b$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub_b, '\\)\\"[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), 4.5, tolerance = 1e-4)
  expect_equal(extract_sub_num(sub_b, 'italic\\(p\\)[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), stats::pchisq(4.5, 1, lower.tail = FALSE), tolerance = 1e-3)
  expect_equal(extract_sub_num(sub_b, '\\["Cohen"\\][[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), 0.375, tolerance = 1e-4)

  p_c <- capture_jjpie_plot(opts_b, d_cavo_val, ".plot2")
  sub_c <- paste(deparse(p_c$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub_c, '\\)\\"[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), 100 / 22, tolerance = 1e-4)
  expect_equal(extract_sub_num(sub_c, 'italic\\(p\\)[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), stats::pchisq(100 / 22, 1, lower.tail = FALSE), tolerance = 1e-3)
  expect_equal(extract_sub_num(sub_c, '\\["Cohen"\\][[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), 5 / 22, tolerance = 5e-4)

  d_rev <- data.frame(
    Pre  = factor(c("Neg", "Neg", "Pos", "Pos"), levels = c("Neg", "Pos")),
    Post = factor(c("Neg", "Pos", "Neg", "Pos"), levels = c("Pos", "Neg")),
    n    = c(40, 3, 2, 5)
  )
  p_rev <- capture_jjpie_plot(opts_b, d_rev, ".plot2")
  sub_rev <- paste(deparse(p_rev$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub_rev, '\\)\\"[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), (3 - 2)^2 / (3 + 2), tolerance = 1e-4)
})

test_that("[C08] 2-way Bayesian contingency table log_e(BF01) matches BayesFactor::contingencyTableBF", {
  # BayesFactor::contingencyTableBF(tb, sampleType = "indepMulti", fixedMargin = "rows", priorConcentration = 1)
  d_b2 <- ClinicoPath::jjpiestats_diagnostic
  tb_b2 <- table(d_b2$test_result, d_b2$disease_status)
  bf_b2 <- BayesFactor::contingencyTableBF(
    tb_b2, sampleType = "indepMulti", fixedMargin = "rows", priorConcentration = 1
  )
  exp_log_bf01 <- -as.numeric(BayesFactor::extractBF(bf_b2, logbf = TRUE)$bf)
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "test_result", group = "disease_status", typestatistics = "bayes",
    seed = 20250101, resultssubtitle = TRUE, digits = 4
  )
  p <- capture_jjpie_plot(opts, d_b2, ".plot2")
  sub <- paste(deparse(p$labels$subtitle), collapse = " ")
  expect_equal(extract_sub_num(sub, 'BF\\["01"\\]\\)[[:space:]]*==[[:space:]]*\\"([0-9.eE+-]+)\\"'), exp_log_bf01, tolerance = 1e-4)
})

test_that("[C09] Within-group 1-sample proportion test (proportiontest = TRUE) adds per-group GOF layer", {
  # ggstatsplot::ggpiestats(..., proportion.test = TRUE) adds 1-sample chi2_gof layer per group
  p_f <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", proportiontest = FALSE),
    d_a4_val, ".plot2"
  )
  p_t <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", proportiontest = TRUE),
    d_a4_val, ".plot2"
  )
  expect_identical(length(p_t$layers) - length(p_f$layers), 1L)
})

test_that("[C10] Split By (plot4) per-stratum chi-square matches independent stats::chisq.test per site", {
  # stats::chisq.test(table(sub_df$treatment_response, sub_df$treatment_arm), correct = FALSE)
  d_b1 <- ClinicoPath::jjpiestats_test
  p_b3 <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(
      dep = "treatment_response", group = "treatment_arm", grvar = "hospital_site",
      resultssubtitle = TRUE, digits = 4
    ),
    d_b1, ".plot4"
  )
  sites <- levels(as.factor(d_b1$hospital_site))
  for (i in seq_along(sites)) {
    sub_df <- d_b1[d_b1$hospital_site == sites[i], ]
    ref_stat <- unname(suppressWarnings(
      stats::chisq.test(table(sub_df$treatment_response, sub_df$treatment_arm), correct = FALSE)$statistic
    ))
    sub_txt <- paste(deparse(p_b3[[i]]$labels$subtitle), collapse = "")
    expect_equal(extract_sub_num(sub_txt, '\\)\\" == \\"([0-9.eE+-]+)\\"'), ref_stat, tolerance = 1e-4)
  }

  d_d7 <- data.frame(
    dep  = factor(c(rep(c("CR", "PR"), each = 15), rep(c("CR", "PR", "PD"), each = 10)), levels = c("CR", "PR", "PD")),
    grp  = factor(rep(c("ArmA", "ArmB"), 30), levels = c("ArmA", "ArmB")),
    site = factor(c(rep("Site1", 30), rep("Site2", 30)), levels = c("Site1", "Site2"))
  )
  p_d7 <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", grvar = "site", resultssubtitle = TRUE),
    d_d7, ".plot4"
  )
  expect_false(is.null(p_d7[[1]]$labels$subtitle))
})

test_that("[C11] Sparse Split By notice reports exact Fisher p-values per stratum", {
  # stats::fisher.test(matrix(c(1, 9, 7, 3), 2, 2))$p.value = 0.01977852; matrix(c(2, 8, 6, 4)) = 0.1698023
  d_b4 <- data.frame(
    resp = factor(c("Yes", "No", "Yes", "No", "Yes", "No", "Yes", "No"), levels = c("Yes", "No")),
    arm  = factor(c("A", "A", "B", "B", "A", "A", "B", "B"), levels = c("A", "B")),
    site = factor(c(rep("SiteAlpha", 4), rep("SiteBeta", 4)), levels = c("SiteAlpha", "SiteBeta")),
    n    = c(1, 9, 7, 3, 2, 8, 6, 4)
  )
  res <- suppressWarnings(ClinicoPath::jjpiestats(
    data = d_b4, dep = "resp", group = "arm", grvar = "site", counts = "n"
  ))
  notice_txt <- strip_html_tags(res$notices$content)
  expect_equal(
    extract_sub_num(notice_txt, "SiteAlpha: p = ([0-9]+\\.[0-9]+)"),
    stats::fisher.test(matrix(c(1, 9, 7, 3), 2, 2))$p.value,
    tolerance = 2e-2
  )
  expect_equal(
    extract_sub_num(notice_txt, "SiteBeta: p = ([0-9]+\\.[0-9]+)"),
    stats::fisher.test(matrix(c(2, 8, 6, 4), 2, 2))$p.value,
    tolerance = 2e-2
  )

  res_preset <- suppressWarnings(ClinicoPath::jjpiestats(
    data = d_b4, dep = "resp", group = "arm", grvar = "site", counts = "n",
    typestatistics = "bayes", clinicalpreset = "treatment"
  ))
  expect_match(strip_html_tags(res_preset$notices$content), "Split By panels: use these exact p-values", fixed = TRUE)
})

test_that("[C12] ggpubr donutPlot (addGGPubrDonut = TRUE) renders accurate ring geometry and slice labels", {
  # 1-way donutPlot ring spans full circle [0, 12] on d_a1_val
  p_1way <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", addGGPubrDonut = TRUE),
    d_a1_val, ".plotDonut"
  )
  b_1way <- ggplot2::ggplot_build(p_1way)
  expect_equal(max(b_1way$data[[1]]$ymax), 12)

  p_grp <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", addGGPubrDonut = TRUE),
    d_a4_val, ".plotDonut"
  )
  b_grp <- ggplot2::ggplot_build(p_grp)
  expect_equal(max(b_grp$data[[1]]$ymax[b_grp$data[[1]]$PANEL == 2]), max(b_grp$layout$panel_params[[2]]$theta.range))
  yes_y_p2 <- b_grp$data[[2]]$y[b_grp$data[[2]]$PANEL == 2 & b_grp$data[[2]]$label == "Yes"]
  expect_equal(yes_y_p2, 35)
})

test_that("[C13] Missing-data handling drops NA rows cleanly without corrupting unsplit plots", {
  # Irrelevant column with NAs does not drop rows in .prepareData()
  d_irr <- d_a4_val
  d_irr$unused_na <- c(rep(NA_real_, 40), rnorm(40))
  opts <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", resultssubtitle = TRUE, digits = 4)
  sub_base <- paste(deparse(capture_jjpie_plot(opts, d_a4_val, ".plot2")$labels$subtitle), collapse = "")
  sub_irr  <- paste(deparse(capture_jjpie_plot(opts, d_irr, ".plot2")$labels$subtitle), collapse = "")
  expect_identical(sub_irr, sub_base)

  d_split_na <- d_a4_val
  d_split_na$site <- factor(c(rep("S1", 35), rep("S2", 35), rep(NA, 10)))
  opts_split <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", group = "grp", grvar = "site", resultssubtitle = TRUE, digits = 4
  )
  sub_with_split <- paste(deparse(capture_jjpie_plot(opts_split, d_split_na, ".plot2")$labels$subtitle), collapse = "")
  expect_identical(sub_with_split, sub_base)

  # Explicit <NA> factor level (from addNA / factor(exclude = NULL)) is stripped and dropped as missing
  d_addna <- data.frame(
    dep = addNA(factor(c(rep("Pos", 15), rep("Neg", 15), rep(NA, 5)), levels = c("Pos", "Neg")))
  )
  p_addna <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", resultssubtitle = TRUE),
    d_addna, ".plot1"
  )
  expect_identical(nrow(p_addna$data), 2L)
  expect_identical(sum(p_addna$data$counts), 30L)
})

test_that("[C14] Aggregated counts weighting (tidyr::uncount) reproduces row-expanded data exactly", {
  # Aggregated table with weights wt reproduces d_a4_val subtitle verbatim
  d_agg <- as.data.frame(table(d_a4_val$dep, d_a4_val$grp))
  names(d_agg) <- c("dep", "grp", "wt")
