test_that("[C17] Formatting options (digits, conflevel, label) control CI width and slice labels", {
  # CI width increases monotonically with conflevel (0.90 < 0.95 < 0.99)
  get_w <- function(cl) {
    p <- capture_jjpie_plot(
      ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", conflevel = cl, resultssubtitle = TRUE, digits = 5),
      d_a4_val, ".plot2"
    )
    sub <- paste(deparse(p$labels$subtitle), collapse = "")
    m <- regmatches(sub, regexpr('\\[" \\* "[0-9.]+", "[0-9.]+" \\* "\\]', sub))
    nums <- as.numeric(regmatches(m, gregexpr("[0-9]+\\.[0-9]+", m))[[1]])
    nums[2] - nums[1]
  }
  expect_lt(get_w(0.90), get_w(0.95))
  expect_lt(get_w(0.95), get_w(0.99))

  d_rare <- data.frame(dep = factor(c("Rare", rep("Common", 249)), levels = c("Rare", "Common")))
  p_rare <- capture_jjpie_plot(
    ClinicoPath:::jjpiestatsOptions$new(dep = "dep", label = "percentage", digits = 2),
    d_rare, ".plot1"
  )
  expect_false(identical(p_rare$data$.label[p_rare$data$dep == "Rare"], "0%"))
})

