test_that("[C22] Paired McNemar guards enforce 2x2 structure, N >= 10, discordant thresholds, and matching levels", {
  # N = 9 refused; N = 10 accepted; m = 0, 3, 4, 10 notices match exact thresholds
  mcn_df <- function(a, b, c, d) {
    data.frame(
      Pre  = factor(c("Neg", "Pos", "Neg", "Pos"), levels = c("Neg", "Pos")),
      Post = factor(c("Neg", "Neg", "Pos", "Pos"), levels = c("Neg", "Pos")),
      n    = c(a, c, b, d)
    )
  }
  r9  <- suppressWarnings(ClinicoPath::jjpiestats(data = mcn_df(2, 3, 2, 2), dep = "Pre", group = "Post", counts = "n", paired = TRUE))
  r10 <- suppressWarnings(ClinicoPath::jjpiestats(data = mcn_df(3, 3, 2, 2), dep = "Pre", group = "Post", counts = "n", paired = TRUE))
  rm0 <- suppressWarnings(ClinicoPath::jjpiestats(data = mcn_df(10, 0, 0, 10), dep = "Pre", group = "Post", counts = "n", paired = TRUE))
  rm3 <- suppressWarnings(ClinicoPath::jjpiestats(data = mcn_df(10, 3, 0, 10), dep = "Pre", group = "Post", counts = "n", paired = TRUE))
  rm4 <- suppressWarnings(ClinicoPath::jjpiestats(data = mcn_df(10, 4, 0, 10), dep = "Pre", group = "Post", counts = "n", paired = TRUE))
  expect_match(strip_html_tags(r9$notices$content), "fewer than 10 paired observations", fixed = TRUE)
  expect_no_match(strip_html_tags(r10$notices$content), "fewer than 10 paired observations", fixed = TRUE)
  expect_match(strip_html_tags(rm0$notices$content), "No discordant pairs", fixed = TRUE)
  expect_match(strip_html_tags(rm3$notices$content), "cannot reach p < 0.05", fixed = TRUE)
  expect_match(strip_html_tags(rm4$notices$content), "Few discordant pairs", fixed = TRUE)

  d_long <- data.frame(
    Response  = factor(c("Neg", "Pos", "Neg", "Pos"), levels = c("Neg", "Pos")),
    Timepoint = factor(c("Pre", "Pre", "Post", "Post"), levels = c("Pre", "Post")),
    n         = c(45, 5, 45, 5)
  )
  r_long <- suppressWarnings(ClinicoPath::jjpiestats(
    data = d_long, dep = "Response", group = "Timepoint", counts = "n", paired = TRUE
  ))
  expect_match(strip_html_tags(r_long$notices$content), "Paired analysis not shown", fixed = TRUE)

  # Weighted paired 2x2 with a 0-weight 3rd unused level is accepted as 2x2
  d_wp3 <- data.frame(
    pre  = factor(c("Pos", "Pos", "Neg", "Neg", "Indet"), levels = c("Pos", "Neg", "Indet")),
    post = factor(c("Pos", "Neg", "Pos", "Neg", "Indet"), levels = c("Pos", "Neg", "Indet")),
    n    = c(15, 3, 8, 12, 0)
  )
  r_wp3 <- suppressWarnings(ClinicoPath::jjpiestats(
    data = d_wp3, dep = "pre", group = "post", counts = "n", paired = TRUE
  ))
  expect_no_match(strip_html_tags(r_wp3$notices$content), "3×3 levels", fixed = TRUE)

  # Split By with paired = TRUE warns when a stratum has < 10 pairs or 0 discordant pairs
  d_pair_split <- data.frame(
    pre  = factor(c(rep("Pos", 10), rep("Neg", 10), rep("Pos", 2), rep("Neg", 2)), levels = c("Pos", "Neg")),
    post = factor(c(rep("Pos", 8), rep("Neg", 12), rep("Pos", 2), rep("Neg", 2)), levels = c("Pos", "Neg")),
    site = factor(c(rep("SiteA", 20), rep("SiteB", 4)), levels = c("SiteA", "SiteB"))
  )
  r_pair_split <- suppressWarnings(ClinicoPath::jjpiestats(
    data = d_pair_split, dep = "pre", group = "post", grvar = "site", paired = TRUE
  ))
  expect_match(strip_html_tags(r_pair_split$notices$content), "SiteB", fixed = TRUE)
})

