test_that("[C34] Aggregated counts path raises no tidyselect deprecation warning", {
  agg <- data.frame(
    dep = factor(c("Yes", "No", "Yes", "No")),
    grp = factor(c("A", "A", "B", "B")),
    n   = c(30, 10, 10, 30)
  )
  opts <- ClinicoPath:::jjpiestatsOptions$new(dep = "dep", group = "grp", counts = "n")
  a <- ClinicoPath:::jjpiestatsClass$new(options = opts, data = agg)
  suppressMessages(a$run())
  priv <- a$.__enclos_env__$private
  f <- tempfile(fileext = ".pdf"); grDevices::pdf(f)
  on.exit({ try(grDevices::dev.off(), silent = TRUE); unlink(f) }, add = TRUE)
  warns <- character()
  withCallingHandlers(
    {
      priv$.plot1(image = a$results$plot1, ggtheme = ggplot2::theme_bw(), theme = list())
      priv$.plot2(image = a$results$plot2, ggtheme = ggplot2::theme_bw(), theme = list())
    },
    warning = function(w) { warns <<- c(warns, conditionMessage(w)); invokeRestart("muffleWarning") },
    lifecycle_soft_deprecated = function(w) { warns <<- c(warns, conditionMessage(w)) }
  )
  expect_false(any(grepl("external vector", warns, fixed = TRUE)))
})

test_that("[C35] Bayesian plot rendering does not overwrite the run status in todo", {
  # .plot2/.plot4 used to write "Computing Bayesian analysis..." into `todo`
  # during .plot(); jamovi discards that, but under R it replaced the status.
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = "dep", group = "grp", grvar = "site", typestatistics = "bayes",
    seed = 20250101, resultssubtitle = TRUE
  )
  d <- d_a4_val
  d$site <- factor(rep(c("S1", "S2"), 40))
  a <- ClinicoPath:::jjpiestatsClass$new(options = opts, data = d)
  suppressWarnings(suppressMessages(a$run()))
  before <- strip_html_tags(a$results$todo$content)
  priv <- a$.__enclos_env__$private
  f <- tempfile(fileext = ".pdf"); grDevices::pdf(f)
  on.exit({ try(grDevices::dev.off(), silent = TRUE); unlink(f) }, add = TRUE)
  suppressWarnings(suppressMessages({
    priv$.plot2(image = a$results$plot2, ggtheme = ggplot2::theme_bw(), theme = list())
    priv$.plot4(image = a$results$plot4, ggtheme = ggplot2::theme_bw(), theme = list())
  }))
  after <- strip_html_tags(a$results$todo$content)
  expect_identical(after, before)
  expect_match(after, "80 observations", fixed = TRUE)
  expect_false(grepl("Computing Bayesian", after, fixed = TRUE))
})

