    data = d, dep = "resp", group = "arm", grvar = "site", counts = "n", resultssubtitle = TRUE
  ))
  n_txt <- strip_html_tags(res$notices$content)
  expect_false(grepl("chi-square shown on that panel", n_txt, fixed = TRUE))
  expect_match(n_txt, "so a chi-square test is unreliable there", fixed = TRUE)
  ref <- stats::fisher.test(matrix(c(1, 9, 7, 3), 2, 2))$p.value
  panel_p <- extract_sub_num(paste(deparse(p[[1]]$labels$subtitle), collapse = " "),
                             '\\["Fisher"\\][[:space:]]*==[[:space:]]*\\"([0-9.]+)\\"')
  # The subtitle prints p to 3 decimals (digits = 3): compare with the rounded oracle.
  expect_equal(panel_p, round(ref, 3), tolerance = 1e-8)
  expect_equal(extract_sub_num(n_txt, "S1: p = ([0-9]+\\.[0-9]+)"), ref, tolerance = 2e-2)
})

test_that("[C37] Every visible: expression in jjpiestats.r.yaml evaluates under jmvcore", {
  # `(dep && !paired)` compiled fine but jmvcore could not evaluate it (dep is a
  # character value), so every call failed. Evaluate each expression directly.
  yml_path <- test_path("..", "..", "jamovi", "jjpiestats.r.yaml")
  skip_if_not(file.exists(yml_path), "jamovi/jjpiestats.r.yaml not reachable from the test directory")
  yml <- yaml::read_yaml(yml_path)
  exprs <- unique(Filter(is.character, lapply(yml$items, `[[`, "visible")))
  for (opt_args in list(list(), list(dep = "a"), list(dep = "a", paired = TRUE),
                        list(dep = "a", group = "b", grvar = "c", addGGPubrDonut = TRUE))) {
    o <- do.call(ClinicoPath:::jjpiestatsOptions$new, opt_args)
    for (e in exprs)
      expect_false(inherits(try(o$eval(e), silent = TRUE), "try-error"), info = e)
  }
  plot1_vis <- Filter(function(it) identical(it$name, "plot1"), yml$items)[[1]]$visible
  expect_false(isTRUE(ClinicoPath:::jjpiestatsOptions$new(dep = "a", paired = TRUE)$eval(plot1_vis)))
  expect_true(isTRUE(ClinicoPath:::jjpiestatsOptions$new(dep = "a")$eval(plot1_vis)))
})

test_that("[C38] asSource() and .effectiveOptionsList() harden against injected options and out-of-range values", {
  opts <- ClinicoPath:::jjpiestatsOptions$new(
    dep = 'x"); system("id"); ("',
    ratio = '0.5,0.5"); system("id"); ("'
  )
  # Simulate tampered .omv option values and an undeclared option
  opts$.__enclos_env__$private$..typestatistics$.__enclos_env__$private$.value <- 'bayes"); system("id"); ("'
  evil_opt <- jmvcore::OptionString$new("evil_injected", value = 'y"); system("id"); ("', default = "")
  opts$.addOption(evil_opt)

  a <- ClinicoPath:::jjpiestatsClass$new(options = opts, data = d_a4_val)
  src <- a$asSource()
  parsed <- parse(text = src)
  expect_length(parsed, 1L)
  expect_false(grepl("evil_injected", src, fixed = TRUE))

  # Walk AST to confirm `system` never appears as a call head
  call_heads <- character()
  walk_calls <- function(expr) {
    if (is.call(expr)) {
      call_heads <<- c(call_heads, paste(deparse(expr[[1]]), collapse = ""))
      lapply(as.list(expr)[-1], walk_calls)
    }
  }
  walk_calls(parsed[[1]])
  expect_false("system" %in% call_heads)

  # Out-of-range numeric and enum options clamp to safe defaults in .effectiveOptionsList()
  opts$.__enclos_env__$private$..conflevel$.__enclos_env__$private$.value <- 2.5
  opts$.__enclos_env__$private$..digits$.__enclos_env__$private$.value <- -3L
  opts$.__enclos_env__$private$..label$.__enclos_env__$private$.value <- "invalid_label"
  eff <- a$.__enclos_env__$private$.effectiveOptionsList()
  expect_identical(eff$typestatistics, "parametric")
  expect_identical(eff$label, "percentage")
  expect_identical(eff$conflevel, 0.95)
  expect_identical(eff$digits, 2L)
})
